"""Reproducible regression runner; --integration actually rebuilds all reviewed parts."""
import argparse,hashlib,io,json,os,shutil,subprocess,sys,time,unittest
from datetime import datetime,timezone,timedelta
from pathlib import Path
ROOT=Path(__file__).resolve().parents[1]

def input_fingerprints(root):
    """Snapshot source/test inputs recursively, excluding generated bytecode."""
    root=Path(root);inputs={root/'lc2a.ps1',root/'test.ps1',root/'config.json'}
    for name in ('src','tests','docs/datasheets'):
        for path in (root/name).rglob('*'):
            rel=path.relative_to(root/name)
            if '__pycache__' in rel.parts or path.suffix in ('.pyc','.pyo'):continue
            if path.is_file():inputs.add(path)
    return {path.relative_to(root).as_posix():hashlib.sha256(path.read_bytes()).hexdigest() for path in sorted(inputs)}

def input_changes(before,after):
    added=sorted(after.keys()-before.keys());removed=sorted(before.keys()-after.keys())
    modified=sorted(name for name in before.keys()&after.keys() if before[name]!=after[name])
    return {'added':added,'removed':removed,'modified':modified}

def main():
    ap=argparse.ArgumentParser();ap.add_argument('--integration',action='store_true')
    ap.add_argument('--library-trial',action='store_true',help='Explicit temporary publication into the private library, then cleanup')
    args=ap.parse_args()
    dest=ROOT/'outputs'/'程序测试'/(time.strftime('%Y%m%d_%H%M%S')+'_'+os.urandom(2).hex());dest.mkdir(parents=True)
    hashes=None
    summary={'status':'failed','integration_requested':args.integration,'integration':[],'program_sha256':{}}
    try:
        hashes=input_fingerprints(ROOT);summary['program_sha256']=hashes
        for rel,expected in hashes.items():
            copy=dest/'program'/rel;copy.parent.mkdir(parents=True,exist_ok=True);shutil.copy2(ROOT/rel,copy)
            if hashlib.sha256(copy.read_bytes()).hexdigest()!=expected:raise RuntimeError('Input changed while copying snapshot: '+rel)
        if args.integration:
            for lcsc,name,ref,label,key in [('C8734','LC_C8734_STM32F103C8_LQFP48','U','F103贴片 中文测试','f103'),('C53568','LC_C53568_1N4007_DO41_P8P7','D','真实通孔 中文测试','pth'),('C62715','LC_C62715_LTV817A_DIP4','U','光耦通孔 中文测试','opto')]:
                cmd=[sys.executable,str(ROOT/'src/lc2a.py'),'convert','--lcsc',lcsc,'--name',name,'--refdes',ref,'--label',label,'--profile',lcsc]
                p=subprocess.run(cmd,capture_output=True,encoding='utf-8',timeout=240)
                (dest/(key+'_convert.txt')).write_text(p.stdout+p.stderr,encoding='utf-8')
                if p.returncode:raise RuntimeError('Conversion failed: '+lcsc)
                info=json.loads(p.stdout)
                (ROOT/'work'/(key+'_v2.json')).write_text(p.stdout,encoding='utf-8')
                p=subprocess.run([sys.executable,str(ROOT/'src/verify.py'),'--job',info['job']],capture_output=True,encoding='utf-8',timeout=240)
                (dest/(key+'_verify.txt')).write_text(p.stdout+p.stderr,encoding='utf-8')
                if p.returncode:raise RuntimeError('Independent verification failed: '+lcsc)
                r=json.loads(p.stdout);summary['integration'].append({'lcsc':lcsc,'job':info['job'],'status':r['status'],'output_directory':r['output_directory']})
        stream=io.StringIO();suite=unittest.defaultTestLoader.discover(str(ROOT/'tests'))
        result=unittest.TextTestRunner(stream=stream,verbosity=2).run(suite)
        text=stream.getvalue();(dest/'regression.txt').write_text(text,encoding='utf-8');print(text)
        summary.update(tests_run=result.testsRun,failures=len(result.failures),errors=len(result.errors),skipped=len(result.skipped))
        summary['status']='passed' if result.wasSuccessful() and not result.skipped else 'failed'
        if result.skipped:summary['error']='Some real-sample tests were skipped; run test.ps1 -Integration first.'
        if args.library_trial and summary['status']=='passed':
            from library import trial_job
            summary['library_trials']=[]
            for key,category in [('f103','MCU'),('pth','Diode'),('opto','Isolation')]:
                info=json.loads((ROOT/'work'/(key+'_v2.json')).read_text(encoding='utf-8-sig'))
                summary['library_trials'].append(trial_job(info['job'],'E:/Allegro_Lib',category,True,
                    '本轮实际转换、原生加载与独立几何测试通过；仅测试分类入库并清理；未进行制造或实物装配验证。'))
    except Exception as exc:summary.update(status='failed',error=str(exc))
    if hashes is not None:
        try:
            after=input_fingerprints(ROOT);changes=input_changes(hashes,after)
            summary['program_sha256_after']=after;summary['program_input_changes']=changes
            changed=sorted(changes['added']+changes['removed']+changes['modified'])
            if changed:summary.update(status='failed',error='Program inputs changed during the test run',changed_program_files=changed)
        except Exception as exc:summary.update(status='failed',error='Could not verify final program inputs: '+str(exc))
    summary['report_directory']=str(dest)
    for p in [dest/'summary.json',ROOT/'outputs/程序测试_latest.json']:
        p.write_text(json.dumps(summary,ensure_ascii=False,indent=2),encoding='utf-8')
    now=datetime.now(timezone.utc);bj=now.astimezone(timezone(timedelta(hours=8)))
    lines=[f'# 程序测试记录：{bj:%Y-%m-%d %H:%M:%S} 北京时间','',
        f'- UTC：{now:%Y-%m-%d %H:%M:%S}',f'- 结果：**{summary["status"]}**',
        f'- 完整原生转换与验收：{args.integration}；私人库临时入库清理：{args.library_trial}',
        f'- 用例：{summary.get("tests_run",0)}；失败：{summary.get("failures",0)}；错误：{summary.get("errors",0)}；跳过：{summary.get("skipped",0)}',
        '- 原始证据：本目录 summary.json、regression.txt 及转换/验收日志。',
        '- 程序、测试及docs/datasheets厂家资料快照：program/；递归清单与SHA256记录在summary.json，开始和结束的新增、删除或修改会使本轮失败。',
        '- 限制：程序几何和文件功能测试，不等于制造、实物装配、整板电气/安规验证。','']
    for part in summary['integration']:lines.append(f'- {part["lcsc"]}：{part["status"]}；输出：`{part["output_directory"]}`')
    for trial in summary.get('library_trials',[]):lines.append(f'- 入库 {trial["category"]}：{trial["status"]}；原库哈希恢复：{trial["library_restored"]}；记录：`{trial["receipt"]}`')
    if summary.get('error'):lines+=['',f'错误：{summary["error"]}']
    (dest/'测试报告.md').write_text('\n'.join(lines)+'\n',encoding='utf-8')
    with (ROOT/'outputs/测试记录.md').open('a',encoding='utf-8') as f:
        f.write(f'\n## 自动测试：{bj:%Y-%m-%d %H:%M:%S} 北京时间 / {now:%H:%M:%S} UTC\n\n'+
            '\n'.join(lines[2:])+f'\n\n完整报告：`{dest.relative_to(ROOT / "outputs").as_posix()}/测试报告.md`\n')
    print(json.dumps(summary,ensure_ascii=False,indent=2))
    return 0 if summary['status']=='passed' else 1

if __name__=='__main__':
    for s in (sys.stdout,sys.stderr):
        if hasattr(s,'reconfigure'):s.reconfigure(encoding='utf-8')
    sys.exit(main())
